fn strange_sort_list_helper(s: Vec<i8>) -> (Vec<i8>, Vec<i8>) {
    // The "first" list is just a permutation of the input (here we take it as the identity permutation).
    let first = s;
    let n = first.len();

    // Build the "second" list by front–back interleaving of `first`.
    let mut second = Vec::with_capacity(n);
    for i in 0..n {
        let half = i / 2;
        // Even i -> take from the front; odd i -> take from the back.
        let idx = if i % 2 == 0 {
            half
        } else {
            n - half - 1
        };
        second.push(first[idx]);
    }

    (first, second)
}

